MATCH (a:PlantItem {tag: 'TK-102'}), (b:PlantItem {tag: 'P-101A'}), (g:PlantItem {tag: 'GTV-1003'})
RETURN EXISTS {
  MATCH (a)((x)-[:line_to]->(y) WHERE x <> g AND y <> g)+(b)
} AS can_flow_without_GTV_1003

MATCH (v:Valve)-[:line_to*1..]->(target:PlantItem {tag: 'P-101B'})
