MATCH (a:PlantItem {tag: 'P-101B'}), (b:PlantItem {tag: 'TK-102'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-101A'}), (p)-[:line_to*1..]->(v:Valve), (v)-[:line_to*0..]->(e:Equipment)
